transaction once $request for 24h {
  let delivery = (
    update deliveries
    where merchant_id = $merchant and id = $id
    when state = "failed"
    set state = "queued"
    return id, state
  );
  insert into outbox (merchant_id, id, kind, delivery_id)
  values ($merchant, $outbox_id, "delivery.requeued", @delivery.row.id);
  emit @delivery.row.id, @delivery.row.state
}

