transaction once $repair_run for 24h {
  update deliveries where merchant_id = $merchant and id = $id
    when state = "failed" set state = "queued";
  attempt {
    insert into repair_tags (merchant_id, delivery_id, tag)
    values ($merchant, $id, "manual")
  } recover (unique_violation) {
    require true
  }
}

