migration require_retry_schedule {
  alter table deliveries add constraint retry_time_present
    check (next_attempt_at is not null) not valid;
  backfill deliveries
    where next_attempt_at is null
    set next_attempt_at = created_at
    batch 500 budget scan_bytes 8MiB;
  alter table deliveries validate constraint retry_time_present;
  alter table deliveries alter column next_attempt_at set required;
  alter table deliveries drop constraint retry_time_present
};

plan migration require_retry_schedule;
apply migration require_retry_schedule digest $plan_digest;
show migration require_retry_schedule;

