ALTER TABLE deliveries ADD COLUMN next_attempt_at timestamptz;
ALTER TABLE deliveries ALTER COLUMN next_attempt_at SET DEFAULT now();
CREATE INDEX CONCURRENTLY retry_schedule
    ON deliveries (merchant_id, state, next_attempt_at, id);

ALTER TABLE deliveries ADD CONSTRAINT retry_time_present
    CHECK (next_attempt_at IS NOT NULL) NOT VALID;

-- Run in repeated bounded transactions until the remaining count is zero.
WITH batch AS (
    SELECT merchant_id, id FROM deliveries
    WHERE next_attempt_at IS NULL
    ORDER BY merchant_id, id LIMIT 500 FOR UPDATE SKIP LOCKED
)
UPDATE deliveries AS d SET next_attempt_at = d.created_at
FROM batch AS b
WHERE d.merchant_id = b.merchant_id AND d.id = b.id
  AND d.next_attempt_at IS NULL;

ALTER TABLE deliveries VALIDATE CONSTRAINT retry_time_present;
ALTER TABLE deliveries ALTER COLUMN next_attempt_at SET NOT NULL;
ALTER TABLE deliveries DROP CONSTRAINT retry_time_present;

create procedure billing.retry_one (p_merchant int64, p_delivery int64) {
  let changed = (
    update billing.deliveries where merchant_id = $p_merchant and id = $p_delivery
    when state = "failed" set state = "queued"
    return id, state
  );
  emit @changed.row.id, @changed.row.state
};

run billing.retry_one(p_merchant = 42, p_delivery = 8172) once $request for 24h;

