create role repairer;
grant read (merchant_id, id, state, attempts), update (state, attempts)
  on table deliveries to repairer;
grant role repairer to principal "svc/oncall-repair";

create policy merchant_isolation on deliveries to repairer
  visible when merchant_id = context("tenant")
  write when old.merchant_id = context("tenant")
         and new.merchant_id = context("tenant");

create task "inc-436" for principal "svc/oncall-repair" on deliveries
  visible when merchant_id = 42
  allow update (state)
  from old.state = "failed" to new.state = "queued"
  at most 25 distinct rows and 25 transitions
  expires timestamp("2026-11-05T17:30:00Z") approve above 5;

preview {
  update many deliveries
  where merchant_id = 42 and state = "failed"
  set state = "queued"
  at most 25
} using task "inc-436";

approve change $change digest $digest;
apply change $change digest $digest once $request for 24h;
outcome $request;

