  SELECT merchant_id, id, payload,
         row_number() OVER (
           PARTITION BY merchant_id ORDER BY created_at DESC, id DESC
         ) AS pos
  FROM deliveries WHERE state = 'failed'
) AS r WHERE pos <= 3 ORDER BY merchant_id, pos;

